-- Known starting data, for the demo and for every test. Not business logic:
-- tests call demo_data.reset as a fixture before each scenario.
create or replace package demo_data as
  procedure reset;
end demo_data;
/

create or replace package body demo_data as

  procedure restart_identity(p_table varchar2, p_start number) is
  begin
    execute immediate 'alter table ' || p_table ||
      ' modify id generated by default as identity (start with ' || p_start || ')';
  end;

  procedure reset is
  begin
    execute immediate 'alter table orders disable all triggers';
    execute immediate 'alter table customers disable all triggers';
    delete from audit_log;
    delete from orders;
    delete from customers;
    insert into customers (id, name, credit_limit, active) values (1, 'Acme Corp', 5000, 'Y');
    insert into customers (id, name, credit_limit, active) values (2, 'Globex', 1000, 'Y');
    insert into customers (id, name, credit_limit, active) values (3, 'Initech', 2000, 'N');
    insert into orders (id, customer_id, product, quantity, unit_price, discount_pct, total, status, created_at)
    values (1, 1, 'Widget', 5, 20, 0, 100, 'NEW', date '2026-01-10');
    insert into orders (id, customer_id, product, quantity, unit_price, discount_pct, total, status, created_at)
    values (2, 1, 'Gadget', 12, 50, 5, 570, 'SHIPPED', date '2026-01-11');
    insert into orders (id, customer_id, product, quantity, unit_price, discount_pct, total, status, created_at)
    values (3, 2, 'Sprocket', 3, 100, 0, 300, 'CANCELLED', date '2026-01-12');
    commit;
    execute immediate 'alter table orders enable all triggers';
    execute immediate 'alter table customers enable all triggers';
    restart_identity('customers', 100);
    restart_identity('orders', 100);
    restart_identity('audit_log', 1);
  end;

end demo_data;
/
